    [Test]public void OriginalMalformedSeaMeshIsRejectedByActualRowAndTriangleGeometryGuard()
    {
        const string path="Assets/TruckDragonKingdom/VisualCandidates/RoundedIntegrated20/Models/Actual RiverModeler coastal sea.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);Assert.That(mesh,Is.Not.Null,"Retained real20 corruption is the regression witness, never synthetic expected values.");
