        var type=Type.GetType("LWS.TruckDragonKingdom.Editor.DragonKingdomRegionalWorldIntegration, Assembly-CSharp-Editor",true);var evidence=Activator.CreateInstance(type.GetNestedType("CoastalBand"));var root=new GameObject("Temporary malformed-sea read-only regression");string before;using(var hash=SHA256.Create())before=BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path)));
        try{var error=Assert.Throws<System.Reflection.TargetInvocationException>(()=>type.GetMethod("ValidateStraightSeaGeometry").Invoke(null,new object[]{root.transform,mesh,2,evidence}));Assert.That(error.InnerException,Is.TypeOf<InvalidOperationException>());Assert.That((bool)Field(evidence,"exactStraightSeaGeometry"),Is.False);Assert.That((int)Field(evidence,"invertedSeaTriangles"),Is.GreaterThan(0));Assert.That((float)Field(evidence,"maximumSeaRowDrift"),Is.GreaterThan(12000));}
        finally{UnityEngine.Object.DestroyImmediate(root);using(var hash=SHA256.Create())Assert.That(BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path))),Is.EqualTo(before),"Original20 mesh must remain exact.");}
    }


    [UnityTest,Timeout(1500000)]
    public IEnumerator MeasuredRoundedVistaAndRealDiggerPreserveAcceptedSourcesAndPassCompleteWorldGates()
    {
        const string generated="Assets/TruckDragonKingdom/Tests/World/Generated/";
        Directory.CreateDirectory(generated);AssetDatabase.Refresh();
        for(int i=0;i<SceneManager.sceneCount;i++)
        {
            var scene=SceneManager.GetSceneAt(i);
            if(Application.isBatchMode&&string.IsNullOrEmpty(scene.path))Assert.That(EditorSceneManager.SaveScene(scene,generated+"RoundedWorldRunner-"+Guid.NewGuid().ToString("N")+".unity"),Is.True);
            Assert.That(scene.isDirty||string.IsNullOrEmpty(scene.path),Is.False,"Preserve actual user scenes before isolated rounded world authoring.");
        }
        var setup=EditorSceneManager.GetSceneManagerSetup();var before=setup.ToDictionary(s=>s.path,s=>File.ReadAllBytes(s.path));
        var isolated=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
        Assert.That(EditorSceneManager.SaveScene(isolated,generated+"RoundedWorldIsolation-"+Guid.NewGuid().ToString("N")+".unity"),Is.True);
        var excavation=Type.GetType("LWS.TruckDragonKingdom.Editor.DragonKingdomDiggerCavernAuthoring, Assembly-CSharp-Editor",true);
        try
        {
            var type=Type.GetType("LWS.TruckDragonKingdom.Editor.DragonKingdomRegionalWorldIntegration, Assembly-CSharp-Editor",true);
            var iterator=(IEnumerator)type.GetMethod("CreateRoundedReviewCandidate",Type.EmptyTypes).Invoke(null,null);
            // Execute the real full asynchronous voxel/mesh iterator. No mocks,
            // skipped support gates, Task.Wait, or partial generation shortcut.
            yield return iterator;
            var receipt=type.GetProperty("LastReceipt").GetValue(null);
            object Field(object o,string name)=>o.GetType().GetField(name).GetValue(o);
            Assert.That((string)Field(receipt,"status"),Is.EqualTo("PHYSICAL_GATES_PASSED_REQUIRES_RENDER_AND_ACTUAL_DRIVING_REVIEW"));
            foreach(string n in new[]{"sourceBytesPreserved","roadsAndCriticalPosesExact","originalPhysicalGatesPassed","broadVendorHighlandMassRetained"})Assert.That((bool)Field(receipt,n),Is.True,n);
            var urban=Field(receipt,"urbanBanks");Assert.That(urban,Is.Not.Null);foreach(string n in new[]{"passed","neverLowered","outsideMaskExact","waterCoreExact","roadsAndPosesExact","seamsExact"})Assert.That((bool)Field(urban,n),Is.True,n);Assert.That((int)Field(urban,"outsideChangedSamples"),Is.Zero);Assert.That((float)Field(urban,"maximumOutsideDelta"),Is.Zero);foreach(var district in (Array)Field(urban,"districts")){bool village=(string)Field(district,"region")=="village";Assert.That((int)Field(district,"samples"),Is.EqualTo(1073));Assert.That((int)Field(district,"originalDrySamples"),Is.EqualTo(village?571:1073));Assert.That((int)Field(district,"retainingDrySamples"),Is.EqualTo(village?743:1073));Assert.That((int)Field(district,"newDrySamples"),Is.EqualTo(village?172:0));Assert.That((int)Field(district,"newDryStillUnderSea"),Is.Zero);Assert.That(((Array)Field(district,"points")).Length,Is.EqualTo(1073));}
            var palette=Field(receipt,"palette");Assert.That(palette,Is.Not.Null);Assert.That((bool)Field(palette,"passed"),Is.True);Assert.That((bool)Field(palette,"appearanceOperationsPreservedGeometryAndAlpha"),Is.True);Assert.That((int)Field(palette,"terrains"),Is.EqualTo(16));Assert.That((int)Field(palette,"clonedOuterTerrainData"),Is.EqualTo(12));Assert.That(((Array)Field(palette,"layers")).Length,Is.EqualTo(4));foreach(var paletteTile in (Array)Field(palette,"tiles"))foreach(string field in new[]{"heights","alpha","holes"})Assert.That((string)Field(paletteTile,field+"After"),Is.EqualTo((string)Field(paletteTile,field+"Before")),field+" actual appearance operation");
            var dry=(Array)Field(receipt,"settlementDryLand");Assert.That(dry.Length,Is.EqualTo(2));
            foreach(var district in dry){bool village=(string)Field(district,"region")=="village";Assert.That((int)Field(district,"samples"),Is.EqualTo(1073));Assert.That((int)Field(district,"dryYardSamples"),Is.EqualTo(village?743:1073));Assert.That((int)Field(district,"dryYardSamples")+(int)Field(district,"declaredWaterOrBankSamples"),Is.EqualTo(1073));Assert.That((int)Field(district,"unexpectedUnderSea"),Is.Zero);Assert.That((float)Field(district,"minimumFreeboard"),Is.GreaterThanOrEqualTo(1.5f));Assert.That((int)Field(district,"buildings"),Is.EqualTo(village?13:8));Assert.That((int)Field(district,"floodedBuildingFootSamples"),Is.Zero);Assert.That((float)Field(district,"minimumBuildingFreeboard"),Is.GreaterThanOrEqualTo(1.5f));Assert.That((int)Field(district,"dryDecorations"),Is.EqualTo(village?44:0));Assert.That((int)Field(district,"deckSupportedDecorations"),Is.EqualTo(village?0:22));Assert.That((int)Field(district,"deckFootSamples"),Is.EqualTo(village?0:198));Assert.That((int)Field(district,"floodedDecorationFootSamples"),Is.Zero);if(village)Assert.That((float)Field(district,"minimumDecorationFreeboard"),Is.GreaterThanOrEqualTo(1.5f));Assert.That((bool)Field(district,"passed"),Is.True);}
            var quality=Field(receipt,"terrainQuality");Assert.That(quality,Is.Not.Null);Assert.That((bool)Field(quality,"passed"),Is.True);
            Assert.That((int)Field(quality,"integratedSteep65"),Is.LessThanOrEqualTo((int)Field(quality,"allowedSteep65")));
            Assert.That((int)Field(quality,"integratedSteep80"),Is.LessThanOrEqualTo(500));Assert.That((float)Field(quality,"maximumTileSeamDelta"),Is.LessThanOrEqualTo(.04f));
            var grounding=Field(receipt,"groundingReview");Assert.That(grounding,Is.Not.Null);Assert.That((bool)Field(grounding,"passed"),Is.True);Assert.That((int)Field(grounding,"unsupportedPavement"),Is.Zero);
            var terrains=(Array)Field(receipt,"terrains");Assert.That(terrains.Length,Is.EqualTo(4));
            foreach(var tile in terrains)
            {
                Assert.That((int)Field(tile,"resolution"),Is.EqualTo(513));Assert.That((int)Field(tile,"protectedSamples"),Is.GreaterThan(0));
                Assert.That((int)Field(tile,"transitionSamples"),Is.GreaterThan(0));Assert.That((bool)Field(tile,"protectedSamplesExact"),Is.True);
                Assert.That((bool)Field(tile,"undergroundFoundationExact"),Is.True);
            }
            var cavern=Field(receipt,"cavern");Assert.That(cavern,Is.Not.Null);
            Assert.That((string)Field(cavern,"status"),Is.EqualTo("MEASURED_CAVERN_REQUIRES_FULL_WORLD_GATES_AND_RENDER_REVIEW"));
