            Assert.That((int)Field(cavern,"generatedMeshColliders"),Is.GreaterThan(0));Assert.That((int)Field(cavern,"removedRejectedRoofRocks"),Is.EqualTo(4));
            Assert.That(((Array)Field(cavern,"roof")).Length,Is.EqualTo(187));Assert.That((float)Field(cavern,"minimumClearance"),Is.GreaterThanOrEqualTo(42));
            Assert.That((int)Field(cavern,"roofFailures"),Is.Zero);Assert.That((int)Field(cavern,"preCutRoofColumns"),Is.EqualTo(187));
            Assert.That((int)Field(cavern,"floorRestorationOperations"),Is.EqualTo(1));
            Assert.That((float)Field(cavern,"minimumPreCutSurfaceY"),Is.GreaterThanOrEqualTo(170));
            foreach(string n in new[]{"exactHeightmaps","outsideHolesExact","streamingAssetsUntouched","installedUrpDetectorSatisfied","pipelineSettingsPreserved"})Assert.That((bool)Field(cavern,n),Is.True,n);
            Assert.That(((string[])Field(cavern,"tileDataFolders")).Length,Is.EqualTo(2));Assert.That(((string[])Field(cavern,"streamingAssetsFolders")).Length,Is.EqualTo(2));
            Assert.That(Directory.Exists((string)Field(cavern,"dataFolder")),Is.True,"Actual isolated Digger persistence must exist.");
            Assert.That((bool)excavation.GetProperty("IsBusy").GetValue(null),Is.False);
            Assert.That((int)Field(receipt,"extractionSweepQueries"),Is.GreaterThan(400));Assert.That(((IList)Field(receipt,"extractionFailures")).Count,Is.Zero);
            Assert.That(((Array)Field(receipt,"placements")).Length,Is.GreaterThan(50),"Existing actual scenery must remain and be re-grounded.");
            foreach(string n in new[]{"prefab","preview","definition"})Assert.That(File.Exists((string)Field(receipt,n)),Is.True,n);
            var prefab=AssetDatabase.LoadAssetAtPath<GameObject>((string)Field(receipt,"prefab"));Assert.That(prefab,Is.Not.Null);
            Assert.That(prefab.GetComponentsInChildren<Terrain>(true).All(t=>t.materialTemplate!=null&&t.materialTemplate.shader.name=="Digger/Terrain/URP/Lit"),Is.True);
            var savedWorld=prefab.GetComponent(Type.GetType("LWS.TruckDragonKingdom.DragonKingdomWorld, Assembly-CSharp",true));
            var forest=(Transform)Field(((Array)Field(savedWorld,"regions")).Cast<object>().Single(r=>(string)Field(r,"id")=="forest"),"root");
            var groups=forest.GetComponentsInChildren<LODGroup>(true).Where(g=>g.GetLODs().Length==3).ToArray();Assert.That(groups.Length,Is.GreaterThan(0));
            foreach(var group in groups)Assert.That(group.GetLODs()[2].screenRelativeTransitionHeight,Is.EqualTo(.025f).Within(.00001f),"Owned instance threshold preserves measured overview visibility.");
            if(Environment.GetCommandLineArgs().Contains("-tsDragonFinishArt"))
            {
                var berth=Field(receipt,"berth");Assert.That(berth,Is.Not.Null);foreach(string n in new[]{"passed","outsideMaskExact","neverRaised","seamsExact","shoreExact","ferryBedExact"})Assert.That((bool)Field(berth,n),Is.True,n);Assert.That((int)Field(berth,"outsideChangedSamples"),Is.Zero);Assert.That((float)Field(berth,"maximumOutsideDelta"),Is.Zero);Assert.That((int)Field(berth,"changedSamples"),Is.InRange(1,1499));Assert.That((float)Field(berth,"maximumLowering"),Is.LessThanOrEqualTo(4.04f));foreach(var row in (Array)Field(berth,"tiles"))Assert.That((string)Field(row,"beforeOutsideSha256"),Is.EqualTo((string)Field(row,"afterOutsideSha256")));
                var imports=Field(receipt,"nativeImportPreflight");Assert.That(imports,Is.Not.Null);foreach(string field in new[]{"passed","allUnknownChangesRejected","protectedModelIdentitiesExact"})Assert.That((bool)Field(imports,field),Is.True,field);Assert.That((int)Field(imports,"protectedModels"),Is.EqualTo(3));
                var finish=Field(receipt,"finish");Assert.That(finish,Is.Not.Null);Assert.That((bool)Field(finish,"complete"),Is.True);
                foreach(var expected in new[]{("newStreetfronts",10),("refugeHouses",4),("marketStalls",6),("farmPieces",24),("harborProps",16),("smallMooredBoats",2),("underbrush",140),("mushrooms",36),("cavernCrystals",12),("basalt",24),("alpineRocks",24),("nestRoostTrees",8),("lanterns",28)})Assert.That((int)Field(finish,expected.Item1),Is.EqualTo(expected.Item2),expected.Item1);
                Assert.That((int)Field(finish,"compositionSchema"),Is.EqualTo(3));Assert.That((int)Field(finish,"traderShips"),Is.EqualTo(1));
                foreach(string n in new[]{"ridgeComposition","assemblyMaterials","harborForecourt","harborCargo","retainingBank"})Assert.That((bool)Field(Field(finish,n),"passed"),Is.True,n);var authoredGroups=(Array)Field(finish,"authoredGroups");Assert.That(authoredGroups.Length,Is.EqualTo(5));Assert.That(authoredGroups.Cast<object>().Sum(g=>(int)Field(g,"instances")),Is.EqualTo(335));foreach(var group in authoredGroups){Assert.That((bool)Field(group,"passed"),Is.True);Assert.That(((Array)Field(group,"parts")).Length,Is.EqualTo((int)Field(group,"instances")));}Assert.That((int)Field(Field(finish,"harborForecourt"),"supportedDecorations"),Is.EqualTo(22));Assert.That((int)Field(Field(finish,"harborForecourt"),"decorationFootSamples"),Is.EqualTo(198));Assert.That(((Array)Field(Field(finish,"harborCargo"),"parts")).Length,Is.EqualTo(15));Assert.That((int)Field(Field(finish,"retainingBank"),"stones"),Is.EqualTo(24));
                var artist=Field(finish,"artistMarket");Assert.That(artist,Is.Not.Null);Assert.That((int)Field(artist,"appliedSourceOverrides"),Is.Zero);Assert.That((int)Field(artist,"inactiveSourceOverrides"),Is.EqualTo(12));Assert.That((bool)Field(Field(artist,"materialImports"),"passed"),Is.True);foreach(string n in new[]{"passed","exactSourcePoses","exactDependencies","roadAndObjectiveBuffersClear"})Assert.That((bool)Field(artist,n),Is.True,n);
                foreach(var expected in new[]{("groups",1),("instances",61),("prefabs",28),("groundSamples",49)})Assert.That((int)Field(artist,expected.Item1),Is.EqualTo(expected.Item2));Assert.That(((Array)Field(artist,"children")).Length,Is.EqualTo(61));Assert.That(((Array)Field(artist,"dependencies")).Length,Is.EqualTo(103));Assert.That((float)Field(artist,"supportHeightRange"),Is.LessThanOrEqualTo(.6f));Assert.That((float)Field(artist,"minimumFreeboard"),Is.GreaterThanOrEqualTo(1.5f));
                var ship=Field(finish,"mooredShip");Assert.That(ship,Is.Not.Null);Assert.That((bool)Field(ship,"passed"),Is.True);Assert.That((bool)Field(ship,"originalFerryPoseExact"),Is.True);Assert.That((int)Field(ship,"depthSamples"),Is.EqualTo(25));Assert.That((int)Field(ship,"departureSweepSamples"),Is.EqualTo(53));Assert.That((float)Field(ship,"minimumKeelClearance"),Is.GreaterThanOrEqualTo(3));Assert.That((float)Field(ship,"departureLateralClearance"),Is.GreaterThanOrEqualTo(10));Assert.That((float)Field(ship,"hullLength"),Is.EqualTo(32).Within(.01f));Assert.That((float)Field(ship,"waterlineWidth"),Is.GreaterThanOrEqualTo(5));Assert.That((float)Field(ship,"waterlineLength"),Is.GreaterThanOrEqualTo(15));
                var marketRoot=prefab.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Owned original artist market frontage");Assert.That(marketRoot.childCount,Is.EqualTo(61));
                Type.GetType("LWS.TruckDragonKingdom.Editor.DragonKingdomRegionalWorldIntegration, Assembly-CSharp-Editor",true).GetMethod("ValidateArtistMarket").Invoke(null,new[]{(object)marketRoot,savedWorld,receipt});
                var water=Field(finish,"waterways");Assert.That((bool)Field(water,"originalHeightmapsExact"),Is.True);Assert.That((bool)Field(water,"originalColliderGeometryExact"),Is.True);Assert.That((int)Field(water,"actualBedSamples"),Is.GreaterThan(100));Assert.That((float)Field(water,"maximumSeatedSurfaceGap"),Is.LessThanOrEqualTo(.13f));
                var road=AssetDatabase.LoadAssetAtPath<Material>(Path.GetDirectoryName((string)Field(receipt,"prefab"))+"/Materials/Actual sediment vendor road.mat");Assert.That(road.GetFloat("_OcclusionStrength"),Is.EqualTo(1),"Actual vendor AO multiplier must retain real indirect light inside cavern shadows.");
                const string packedPath="Assets/EasyRoads3D/textures/roads/default_M_S_AO.tga";var packed=AssetDatabase.LoadAssetAtPath<Texture2D>(packedPath);Assert.That(packed,Is.Not.Null);Assert.That(road.GetTexture("_Metallic"),Is.EqualTo(packed),"The actual persistent vendor neutral packed map must survive native save/unload/reload, never a transient builtin.");
                var surfaceBindings=Field(receipt,"surfaceBindings");Assert.That((bool)Field(surfaceBindings,"nonzeroSerializedBinding"),Is.True);Assert.That((bool)Field(surfaceBindings,"reloadedSourceBinding"),Is.True);Assert.That((string)Field(surfaceBindings,"packedMap"),Is.EqualTo(packedPath));Assert.That((string)Field(surfaceBindings,"packedMapGuid"),Is.EqualTo(AssetDatabase.AssetPathToGUID(packedPath)));Assert.That((long)Field(surfaceBindings,"packedMapLocalId"),Is.Not.Zero);Assert.That(AssetDatabase.GetDependencies(AssetDatabase.GetAssetPath(road),true),Does.Contain(packedPath));
                string SourceSha(string path){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
                Assert.That((string)Field(surfaceBindings,"packedMapSha256"),Is.EqualTo(SourceSha(packedPath)));Assert.That((string)Field(surfaceBindings,"packedMapMetaSha256"),Is.EqualTo(SourceSha(packedPath+".meta")));Assert.That((float)Field(surfaceBindings,"metallicPower"),Is.Zero);Assert.That((float)Field(surfaceBindings,"smoothnessPower"),Is.Zero);Assert.That((float)Field(surfaceBindings,"occlusionStrength"),Is.EqualTo(1));
                string savedRoad=File.ReadAllText(AssetDatabase.GetAssetPath(road));Assert.That(System.Text.RegularExpressions.Regex.IsMatch(savedRoad,@"(?m)^    - _Metallic:\r?\n        m_Texture: \{fileID: "+Field(surfaceBindings,"packedMapLocalId")+", guid: "+AssetDatabase.AssetPathToGUID(packedPath)+@", type: 3\}"),Is.True,"Independently inspect native serialized _Metallic GUID/localID; an in-memory assignment cannot pass this gate.");
                Assert.That(prefab.GetComponentsInChildren<Light>(true).Count(l=>l.name=="Original vendor warm lantern light"),Is.EqualTo(28));
                Assert.That((bool)Field(finish,"singleSourceLightPerLantern"),Is.True,"Reuse each vendor lamp's embedded light instead of adding an overlapping duplicate.");
                foreach(var lamp in prefab.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Owned working lantern ",StringComparison.Ordinal)))Assert.That(lamp.GetComponentsInChildren<Light>(true).Length,Is.EqualTo(1));
            }
            if(Environment.GetCommandLineArgs().Contains("-tsDragonOuterBand"))
            {
                var coast=Field(receipt,"outerBand");Assert.That(coast,Is.Not.Null);Assert.That((string)Field(coast,"status"),Is.EqualTo("ATTACHED_REAL_VISTA_COAST_REQUIRES_FULL_WORLD_RENDER_AND_FLIGHT_REVIEW"));
                Assert.That((int)Field(coast,"outerTerrains"),Is.EqualTo(12));Assert.That((int)Field(coast,"totalTerrains"),Is.EqualTo(16));Assert.That(prefab.GetComponentsInChildren<Terrain>(true).Length,Is.EqualTo(16));
                foreach(string name in new[]{"coreHeightmapsExact","coreColliderGeometryExact","sourceBytesPreserved","duplicateLakeRenderingReplaced"})Assert.That((bool)Field(coast,name),Is.True,name);
                var seams=Field(coast,"seams");Assert.That((string[])Field(seams,"issues"),Is.Empty);Assert.That((float)Field(seams,"innerMaximumError"),Is.LessThanOrEqualTo(.04f));Assert.That((float)Field(seams,"outerMaximumError"),Is.LessThanOrEqualTo(.04f));
                Assert.That((bool)Field(coast,"exactStraightSeaGeometry"),Is.True);Assert.That((int)Field(coast,"invalidSeaVertices"),Is.Zero);Assert.That((int)Field(coast,"invertedSeaTriangles"),Is.Zero);Assert.That((float)Field(coast,"maximumSeaRowDrift"),Is.LessThan(.15f));Assert.That((float)Field(coast,"minimumSeaTriangleArea"),Is.GreaterThan(.01f));Assert.That((int)Field(coast,"seaRows"),Is.GreaterThan(2));Assert.That((int)Field(coast,"seaColumns"),Is.GreaterThan(2));Assert.That((int)Field(coast,"seaRows")*(int)Field(coast,"seaColumns"),Is.EqualTo((int)Field(coast,"seaVertices")));
                Assert.That((int)Field(coast,"seaVertices"),Is.GreaterThan(1000));Assert.That(AssetDatabase.LoadAssetAtPath<Mesh>((string)Field(coast,"seaMesh")),Is.Not.Null);
                var neighborhood=prefab.GetComponentsInChildren(Type.GetType("LWS.TruckDragonKingdom.DragonTerrainNeighborhood, Assembly-CSharp",true),true);Assert.That(neighborhood.Length,Is.EqualTo(1));Assert.That(((Array)Field(neighborhood[0],"terrains")).Length,Is.EqualTo(16));
                Assert.That(prefab.GetComponentsInChildren<Renderer>(true).Single(r=>r.name=="Lanternwater Lake").enabled,Is.False,"The original lake identity is retained; one real connected vendor sea replaces duplicate coplanar transparency.");
            }
            foreach(var source in before)Assert.That(File.ReadAllBytes(source.Key),Is.EqualTo(source.Value));
        }
        finally
        {
            if(!(bool)excavation.GetProperty("IsBusy").GetValue(null))EditorSceneManager.RestoreSceneManagerSetup(setup);
            else Debug.LogError("Preserving the isolated rejected world while real Digger jobs remain pending; do not destroy vendor job resources.");
        }
